#include <bits/stdc++.h>
using namespace std;

struct Group {
    int gcdValue;
    int count;
};

struct Node {
    int totalGcd = 0;
    long long good = 0;
    vector<Group> pref, suff;
};

void appendGroup(vector<Group>& groups, int value, int count) {
    if (!groups.empty() && groups.back().gcdValue == value)
        groups.back().count += count;
    else
        groups.push_back({value, count});
}

Node mergeNodes(const Node& a, const Node& b) {
    if (a.totalGcd == 0) return b;
    if (b.totalGcd == 0) return a;

    Node result;
    result.totalGcd = gcd(a.totalGcd, b.totalGcd);
    result.good = a.good + b.good;

    int ptr = (int)b.pref.size();
    long long excluded = 0;
    long long totalRightPrefixes = 0;
    for (const auto& group : b.pref)
        totalRightPrefixes += group.count;

    for (const auto& left : a.suff) {
        while (ptr > 0 && gcd(left.gcdValue, b.pref[ptr - 1].gcdValue) == 1) {
            excluded += b.pref[ptr - 1].count;
            --ptr;
        }
        result.good += 1LL * left.count * (totalRightPrefixes - excluded);
    }

    result.pref.reserve(a.pref.size() + b.pref.size());
    for (const auto& group : a.pref)
        appendGroup(result.pref, group.gcdValue, group.count);
    for (const auto& group : b.pref)
        appendGroup(result.pref, gcd(a.totalGcd, group.gcdValue), group.count);

    result.suff.reserve(a.suff.size() + b.suff.size());
    for (const auto& group : b.suff)
        appendGroup(result.suff, group.gcdValue, group.count);
    for (const auto& group : a.suff)
        appendGroup(result.suff, gcd(b.totalGcd, group.gcdValue), group.count);

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int size = 1;
    while (size < n) size <<= 1;
    vector<Node> tree(2 * size);

    for (int i = 0; i < n; ++i) {
        int value;
        cin >> value;
        Node& leaf = tree[size + i];
        leaf.totalGcd = value;
        leaf.good = (value > 1);
        leaf.pref.push_back({value, 1});
        leaf.suff.push_back({value, 1});
    }

    for (int i = size - 1; i >= 1; --i)
        tree[i] = mergeNodes(tree[2 * i], tree[2 * i + 1]);

    while (m--) {
        int type, x, y;
        cin >> type >> x >> y;

        if (type == 1) {
            int pos = size + x - 1;
            tree[pos] = Node{};
            tree[pos].totalGcd = y;
            tree[pos].good = (y > 1);
            tree[pos].pref.push_back({y, 1});
            tree[pos].suff.push_back({y, 1});

            for (pos >>= 1; pos >= 1; pos >>= 1)
                tree[pos] = mergeNodes(tree[2 * pos], tree[2 * pos + 1]);
        } else {
            int left = size + x - 1;
            int right = size + y;
            Node leftResult, rightResult;

            while (left < right) {
                if (left & 1)
                    leftResult = mergeNodes(leftResult, tree[left++]);
                if (right & 1)
                    rightResult = mergeNodes(tree[--right], rightResult);
                left >>= 1;
                right >>= 1;
            }

            Node answer = mergeNodes(leftResult, rightResult);
            cout << answer.good << '\n';
        }
    }

    return 0;
}
